using System;using Game.Components;using Game.Simulation;using Unity.Entities;using Game.Configs;using Game.Skirmish.Contracts;
namespace Game.Runtime {
// Hot reads check captured launch/session identity only; arbitrary in-place array mutation is not detected here.
// Full compiler/hash/source checks belong to startup and publication boundaries.
// Data-family check only. SourceAdmittedProfiles owns executable mission/seed admission.
internal static class SourceGroundMissionFamily {
 internal static void RequireCatalogSetup(SkirmishResolvedSetup setup){RequireCatalogIdentity(setup);if(setup.CatalogId!="S002"&&!SkirmishGenericGroundEnemyRollout.Supports(setup))throw new NotSupportedException("Original generic-ground capability boundary rejected");}
 internal static void RequireCatalogIdentity(SkirmishResolvedSetup setup){
  if(setup==null)throw new NotSupportedException("Actual retained source setup required");
  if(setup.CatalogId=="S002")return; // Preserve the existing source catalog scope.
  if(!new SkirmishCatalogId(setup.CatalogId).IsValid||setup.DefinitionId!="skirmish."+setup.CatalogId.ToLowerInvariant()||setup.ObjectiveKind!=SkirmishObjectiveKind.BaseAssault||setup.ArmyProfileId!=SkirmishArmyProfileId.GroundManeuver||!GroundMissionContext.SupportsOriginalGroundStart(setup.StartPackageId,setup.Readiness)||string.IsNullOrEmpty(setup.LayoutBindingFingerprint)||string.IsNullOrEmpty(setup.MissionLogicalBindingFingerprint)||setup.EnemyPolicy==null)throw new NotSupportedException("Actual source-compiled source/logical-bound BA/G/Field-or-Established ground-family identity required");
 }
 internal static int SourcePresetLoadIndex(SkirmishResolvedSetup setup,int playableIndex){RequireCatalogIdentity(setup);if(SkirmishMissionDispatch.TryGetLegacyIndex(setup.CatalogId,out int original)){if(playableIndex!=original)throw new NotSupportedException("Original coded dispatch required");return original;}if(playableIndex!=-1)throw new NotSupportedException("Source-only compiled mission must retain Planned/-1");return SkirmishPresetConfig.SourcePresetIndex(-1);}
 internal static SkirmishResolvedSetup RequireSession(EntityManager em,Entity session){if(em==null||!em.Exists(session)||!em.HasComponent<SkirmishResolvedSetupRecord>(session)||!em.HasComponent<SkirmishExpandedSessionComponent>(session)||!em.HasComponent<SkirmishMatchState>(session)||!em.HasComponent<SkirmishLaunchDefinitionRecord>(session))throw new NotSupportedException("Actual compiled source session required");var setup=em.GetComponentObject<SkirmishResolvedSetupRecord>(session).Setup;RequireCatalogIdentity(setup);var state=em.GetComponentData<SkirmishExpandedSessionComponent>(session);var match=em.GetComponentData<SkirmishMatchState>(session);var launch=em.GetComponentObject<SkirmishLaunchDefinitionRecord>(session);if(state.IsLegacy!=0||state.SessionId.IsEmpty||state.SessionId!=match.SessionId||state.CatalogId.ToString()!=setup.CatalogId||state.DefinitionId.ToString()!=setup.DefinitionId||state.ContentVersion!=setup.ContentVersion||state.SetupHash!=setup.SetupHash||state.Seed!=setup.Seed||match.Seed!=setup.Seed||state.SizeId!=setup.SizeId||state.DifficultyId!=setup.DifficultyId||state.ObjectiveKind!=setup.ObjectiveKind||launch==null||!launch.MatchesIdentity(setup,state))throw new NotSupportedException("Compiled source session identity changed");SourcePresetLoadIndex(setup,match.ScenarioIndex);return setup;}
 internal static void RequireLogicalContext(in GroundMissionContext context,SkirmishResolvedSetup setup,in SkirmishExpandedSessionComponent state,int playableIndex){RequireCatalogIdentity(setup);if(context.ObservationScope!=AriaS002Scope.LogicalPublicData||context.SourcePresetLoadIndex!=SourcePresetLoadIndex(setup,playableIndex)||!GroundMissionContextFactory.MatchesLogicalSession(context,setup,state,playableIndex))throw new NotSupportedException("Exact compiled logical family context/session required");}

}
}
